WITH filtered_order_items AS (SELECT * FROM order_items WHERE order_id IN (12, 35, 38) AND quantity <= 5), summary AS (SELECT CASE WHEN unit_price >= 350 THEN 'high' WHEN unit_price >= 130 THEN 'mid' ELSE 'low' END unit_price_bucket, AVG(quantity) avg_quantity, ROUND(AVG(unit_price), 2) avg_unit_price FROM filtered_order_items GROUP BY CASE WHEN unit_price >= 350 THEN 'high' WHEN unit_price >= 130 THEN 'mid' ELSE 'low' END) SELECT * FROM summary
